INSERT INTO `tickets_messages` (`ticket_message_id`, `ticket_id`, `user_id`, `ticket_message`, `ticket_message_date_add`) VALUES
(1, 1, 16, 'Здравствуйте ???? Меня зовут Алихан Я хотел стат администраторам хостинга ', '2023-12-15 16:45:19'),
(2, 1, 1, 'Доброго времени суток Алихан! Мы не проводим наборы в команду хостинга! Следите за нашими новостями в группе ВК. С уважением администрация хостинга Fleen-Host!', '2023-12-15 16:48:40'),
(3, 2, 16, 'На мод не хватет', '2023-12-15 16:50:05'),
(4, 1, 16, 'Оу Никита Я тебя помню врядлм не помниш мен', '2023-12-15 16:50:54'),
(5, 2, 1, 'Здравствуйте, деньги не выдаём, но вы можете пополнить счет аккаунта ', '2023-12-15 20:35:55'),
(6, 2, 16, '15рубл д', '2023-12-15 22:11:27'),
(7, 1, 1, 'Запрос закрыт.', '2023-12-15 23:43:02'),
(8, 2, 1, 'Ваш был дан ответ, запрос закрыт.', '2023-12-15 23:43:37'),
(9, 3, 103, 'Я бы хотел на модератора либо на агента поддержки пойти можно?', '2023-12-16 11:39:55'),
(10, 4, 107, 'А как удалить свой бесплатный сервер?', '2023-12-16 19:31:39'),
(11, 3, 1, 'Pic Мико Го 15.12.2023 в 16:45 Здравствуйте ???? Меня зовут Алихан Я хотел стат администраторам хостинга Pic Никита Громов 15.12.2023 в 16:48 Доброго времени суток Алихан! Мы не проводим наборы в команду хостинга! Следите за нашими новостями в группе ВК. С уважением администрация хостинга Fleen-Host!', '2023-12-16 22:20:01'),
(12, 4, 1, 'Здравствуйте, если вам требуется удалить бесплатный сервер то можете написать в этот чат.', '2023-12-16 22:20:57'),
(13, 4, 1, 'Запрос закрыт.', '2023-12-17 17:47:00'),
(14, 5, 156, '#litewebhost', '2023-12-17 22:24:29'),
(15, 5, 156, '#liteserver', '2023-12-17 22:25:19'),
(16, 5, 156, '#10rubnewyear', '2023-12-17 22:25:50'),
(17, 5, 1, 'Доброго времени суток! Промокод действителен только 1 день, в другие дни доступны новые промокоды которые тоже актуальны на конкретную дату. И промокоды отправляются в группу https://vk.com/fleenhelp', '2023-12-17 22:28:59'),
(18, 6, 241, ' немогу положить деньги  можно я вам переведу а вы положите ', '2023-12-26 20:04:19'),
(19, 6, 1, 'Доброго времени суток Миша! Отпишите в ВК - https://vk.com/fleenhelp. С уважением администрация хостинга Fleen-Host!', '2023-12-26 22:12:38'),
(20, 7, 262, 'На балансе 13р, пытаюсь купить сервер за 7.50р и пишет недостаточно денег на балансе', '2023-12-28 12:16:05'),
(21, 7, 1, 'Здравствуйте! Исправили данную ошибку, попробуйте ещё раз', '2023-12-28 13:58:01'),
